const todas = $input.all().map((i) => i.json);
const linhas = todas.filter((p) => !p.coberto);
const cobertos = todas.filter((p) => p.coberto);
if (linhas.length === 0) {
  return [];
}
const hojeLabel = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const blocos = linhas.map((p, i) => {
  const q = Math.round(Number(p.quantidade_vendida_30d));
  const aviso = Number(p.estoque_irmaos) > 0 ? ' ⚠️ tem pouco em outro cadastro' : '';
  return `${i + 1}. ${p.nome_produto} (cód. ${p.codigo_produto}) — ${q} ${q === 1 ? 'vendido' : 'vendidos'} em 30d${aviso}`;
});

const rodapeCobertos = cobertos.length > 0
  ? `\n\nℹ️ ${cobertos.length} ${cobertos.length === 1 ? 'item zerado já coberto' : 'itens zerados já cobertos'} por outro cadastro (não entram na lista): ${cobertos.map((p) => p.nome_produto).join('; ')}`
  : '';

const mensagem = `📦 *Estoque zerado — produtos de giro alto*\n📅 ${hojeLabel}\n\n${blocos.join('\n')}\n\nRepor com prioridade — são os produtos que mais vendem e estão zerados agora.${rodapeCobertos}`;

return [{ json: { mensagem } }];
